(() => {
  'use strict';
  const storageKey = 'orion.language';
  const choices = new Set(['auto', 'ru', 'en', 'de', 'es']);
  let preference = 'auto';
  let language = 'ru';
  try {
    const saved = localStorage.getItem(storageKey);
    if (choices.has(saved)) preference = saved;
  } catch {
    // Выбор работает и при запрете доступа к хранилищу браузера.
  }

  function resolveSystemLanguage(languages) {
    for (const value of languages) {
      if (typeof value !== 'string') continue;
      const base = value.toLowerCase().split(/[-_]/)[0];
      if (choices.has(base) && base !== 'auto') return base;
    }
    return 'en';
  }

  const nodes = [];
  const walker = document.createTreeWalker(document.documentElement, NodeFilter.SHOW_TEXT);
  while (walker.nextNode()) {
    const node = walker.currentNode;
    if (node.parentElement?.closest('script, style')) continue;
    const source = node.nodeValue.trim();
    if (!Object.hasOwn(translations, source)) continue;
    const start = node.nodeValue.indexOf(source);
    nodes.push({node, source, before: node.nodeValue.slice(0, start), after: node.nodeValue.slice(start + source.length)});
  }
  const attributes = [];
  for (const element of document.querySelectorAll('[aria-label], [alt], meta[name="description"], meta[property="og:title"], meta[property="og:description"]')) {
    for (const name of ['aria-label', 'alt', 'content']) {
      const source = element.getAttribute(name);
      if (source && Object.hasOwn(translations, source)) attributes.push({element, name, source});
    }
  }

  function text(source) {
    if (language === 'ru') return source;
    const index = language === 'de' ? 0 : language === 'es' ? 1 : -1;
    return extraTranslations[source]?.[index] ?? translations[source] ?? source;
  }

  function apply() {
    language = preference === 'auto'
      ? resolveSystemLanguage(navigator.languages?.length ? navigator.languages : [navigator.language])
      : preference;
    document.documentElement.lang = language;
    for (const item of nodes) item.node.nodeValue = item.before + text(item.source) + item.after;
    for (const item of attributes) item.element.setAttribute(item.name, text(item.source));
    for (const select of document.querySelectorAll('[data-language]')) select.value = preference;
    document.dispatchEvent(new CustomEvent('orion:languagechange', {detail: {language, preference}}));
  }

  function selectPreference(value) {
    if (!choices.has(value)) return;
    preference = value;
    try {
      if (value === 'auto') localStorage.removeItem(storageKey);
      else localStorage.setItem(storageKey, value);
    } catch {
      // В текущей вкладке язык переключается даже без сохранения настройки.
    }
    apply();
  }

  window.OrionLocale = Object.freeze({text, resolveSystemLanguage, get language() { return language; }});
  for (const select of document.querySelectorAll('[data-language]')) {
    select.addEventListener('change', () => selectPreference(select.value));
  }
  window.addEventListener('languagechange', () => {
    if (preference === 'auto') apply();
  });
  window.addEventListener('storage', event => {
    if (event.key !== storageKey && event.key !== null) return;
    preference = choices.has(event.newValue) ? event.newValue : 'auto';
    apply();
  });
  apply();
})();
